INSERT INTO transcript_summaries (source_id, source_version, result, input_evidence_ids) SELECT id, #{version}, CAST(#{result} AS jsonb), CAST(#{inputIds} AS jsonb) FROM sources WHERE id = #{id} AND kind = #{kind} AND content = #{content}
AND EXISTS ( SELECT 1 FROM summary_tasks WHERE id = #{taskId,jdbcType=OTHER} AND source_id = #{id} AND status = 'RUNNING' AND attempt = #{attempt} AND lease_until > clock_timestamp() FOR UPDATE )
ON CONFLICT (source_id, source_version) DO NOTHING

mapper.update:
UPDATE summary_tasks SET status = 'SUCCEEDED', lease_until = NULL,
    error_code = NULL, updated_at = clock_timestamp()
WHERE id = #{taskId} AND source_id = #{id} AND status = 'RUNNING'
    AND attempt = #{attempt} AND lease_until > clock_timestamp()
    AND EXISTS (
        SELECT 1 FROM transcript_summaries a JOIN sources s ON s.id = a.source_id
        WHERE s.id = #{id} AND s.kind = #{kind} AND s.content = #{content}
            AND a.source_version = #{version}
    )
